import {cpSync,existsSync,mkdirSync,rmSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const source=path.join(root,'frontend/dist/labtrack/browser');
const target=path.join(root,'src/main/resources/static');
if(!existsSync(path.join(source,'index.html')))throw new Error('Chạy npm run build trong frontend trước.');
// This directory is exclusively generated by this script and excluded from Git.
if(target!==path.join(root,'src/main/resources/static'))throw new Error('Invalid output path');
rmSync(target,{recursive:true,force:true});mkdirSync(target,{recursive:true});cpSync(source,target,{recursive:true});
console.log('Đã đưa bản build Angular vào tài nguyên Spring Boot.');
